  renderPlace(){const query=$('#placeSearch').value.toLowerCase(),shapes=[['cube','Cube','Static mesh'],['sphere','Sphere','Static mesh'],['cylinder','Cylinder','Static mesh'],['torus','Ring','Static mesh'],['crystal','Crystal','Static mesh']],systems=[['light','Point Light','Lighting'],['body','Physics Body','Dynamic rigid body'],['player','Player Start','Character controller'],['terrain','Landscape','Sculptable heightfield']];const render=(items,system)=>items.filter(([,n])=>n.toLowerCase().includes(query)).map(([kind,name,desc])=>`<div class="place-item ${system?'system':''}" data-place="${kind}" draggable="true"><div class="place-icon">${icon(kind)}</div><div><strong>${name}</strong><small>${desc}</small></div></div>`).join('');$('#placeActors').innerHTML=render(shapes,false);$('#placeSystems').innerHTML=render(systems,true);}
  renderOutliner(){const scene=this.activeScene,query=$('#outlinerSearch').value.toLowerCase(),entities=scene.data.entities;$('#actorCount').textContent=entities.length;$('#objectStats').textContent=entities.length+' actors';let html='';const draw=(e,depth)=>{const children=entities.filter(c=>c.parent===e.id),matches=e.name.toLowerCase().includes(query);if(query&&!matches&&!children.some(c=>c.name.toLowerCase().includes(query)))return;const type=e.components.player?'Player':e.components.light?'Light':e.components.graph?'Graph':e.components.mesh?.asset==='terrain'?'Terrain':e.components.body?.type==='dynamic'?'Physics':e.components.mesh?'Mesh':'Group';html+=`<div class="tree-row ${e.id===this.selection?'selected':''} ${e.visible===false?'hidden-actor':''}" data-entity="${esc(e.id)}" role="treeitem" aria-selected="${e.id===this.selection}" style="padding-left:${6+depth*12}px"><span class="tree-arrow" data-fold="${esc(e.id)}">${children.length?this.folded.has(e.id)?'▸':'▾':''}</span><span class="tree-icon">${icon(entityIcon(e))}</span><span class="tree-name">${esc(e.name)}</span><span class="tree-type">${type}</span><button class="eye-toggle" data-visibility="${esc(e.id)}" title="Toggle visibility">${e.visible===false?'○':'◦'}</button></div>`;if(!this.folded.has(e.id)||query)children.forEach(c=>draw(c,depth+1));};entities.filter(e=>!e.parent).forEach(e=>draw(e,0));$('#outlinerTree').innerHTML=html;$('#selectionLabel').textContent=this.selection?scene.get(this.selection)?.name||'No actor selected':`${entities.length} actors in world`;}
